<style>
:root{font-family:system-ui,sans-serif;color:#192534;background:#f3f5f8;color-scheme:light}*{box-sizing:border-box}body{margin:0}main{max-width:800px;margin:48px auto;padding:0 20px}nav{display:flex;gap:20px;flex-wrap:wrap;margin-bottom:32px}a{color:#2258b7}h1{font-size:28px;letter-spacing:-.04em}p{line-height:1.7}.card{background:white;border:1px solid #d9e0e8;border-radius:16px;padding:28px;margin:24px 0}.badge{display:inline-block;background:#e9f1ff;color:#174a91;padding:6px 12px;border-radius:24px;font-size:14px}label{display:block;font-weight:600;margin:20px 0 8px}input,textarea,button{font:inherit}input,textarea{width:100%;padding:12px;border:1px solid #9ba9bb;border-radius:8px}textarea{resize:vertical}button{background:#2258b7;color:white;border:0;border-radius:8px;padding:12px 20px;margin-top:24px;cursor:pointer}button:hover{background:#17438e}:focus-visible{outline:3px solid #347bdf;outline-offset:3px}.errors{background:#fff0ed;border:1px solid #d98b7e;border-radius:8px;padding:16px;color:#912919}.errors ul{margin:8px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;font:inherit;padding:20px;background:#f3f5f8;border-radius:8px}small{color:#4e6074}@media(max-width:520px){main{margin:24px auto}.card{padding:20px}h1{font-size:24px}}
